\echo '=== C3c count small category (20 products)'
EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM (SELECT 1 FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%'))) LIMIT 10001) bounded;
\echo '=== C3b small category sort -updatedAt'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE (p.primary_category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%') OR EXISTS (SELECT 1 FROM catalog_product_category pc WHERE pc.product_id = p.id AND pc.category_id IN (SELECT c.id FROM catalog_category c WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%'))) ORDER BY p.updated_at DESC, p.id DESC LIMIT 26;
\echo '=== C3x alternative: UNION of index lookups (not in code)'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.id IN (SELECT p2.id FROM catalog_product p2 JOIN catalog_category c ON c.id=p2.primary_category_id WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%' UNION SELECT pc.product_id FROM catalog_product_category pc JOIN catalog_category c ON c.id=pc.category_id WHERE c.path LIKE '/d7c098d0-4bae-595e-a1e1-e4a923448956/70134891-dc80-5215-9109-23f8f80ad40a/%') ORDER BY p.name, p.id LIMIT 26;
